BEGIN TRANSACTION;
CREATE TABLE "activity_logs_activitylog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" text NOT NULL, "module" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "ip_address" char(39) NULL, "user_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "files_file" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "size" bigint NOT NULL, "file_type" varchar(100) NOT NULL, "file_field" varchar(100) NOT NULL, "version_number" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "folder_id" bigint NOT NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "files_fileversion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "version_number" integer NOT NULL, "name" varchar(255) NOT NULL, "size" bigint NOT NULL, "file_type" varchar(100) NOT NULL, "file_field" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "file_id" bigint NOT NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "folders_folder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "parent_id" bigint NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "folders_folderpermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_granted" bool NOT NULL, "folder_id" bigint NOT NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_mou" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "mou_number" varchar(100) NOT NULL UNIQUE, "partner_organization" varchar(255) NOT NULL, "department_name" varchar(255) NULL, "effective_date" date NULL, "signed_date" date NULL, "expiry_date" date NULL, "duration_months" integer NOT NULL, "status" varchar(50) NOT NULL, "summary" text NULL, "purpose" text NULL, "objectives" text NULL, "beneficiaries" text NULL CHECK ((JSON_VALID("beneficiaries") OR "beneficiaries" IS NULL)), "opportunities" text NULL CHECK ((JSON_VALID("opportunities") OR "opportunities" IS NULL)), "custom_fields_data" text NULL CHECK ((JSON_VALID("custom_fields_data") OR "custom_fields_data" IS NULL)), "coordinator_name" varchar(255) NULL, "coordinator_designation" varchar(255) NULL, "coordinator_email" varchar(254) NULL, "coordinator_phone" varchar(50) NULL, "partner_name" varchar(255) NULL, "partner_designation" varchar(255) NULL, "partner_email" varchar(254) NULL, "partner_phone" varchar(50) NULL, "additional_notes" text NULL, "remarks" text NULL, "version_number" integer NOT NULL, "is_renewed" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NULL REFERENCES "folders_folder" ("id") DEFERRABLE INITIALLY DEFERRED, "original_mou_id" bigint NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "renewed_from_id" bigint NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "signed_mou_id" bigint NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "mou_type_id" bigint NULL REFERENCES "mous_moutemplate" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_moudocument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "document_type" varchar(50) NOT NULL, "uploaded_at" datetime NOT NULL, "file_id" bigint NOT NULL REFERENCES "files_file" ("id") DEFERRABLE INITIALLY DEFERRED, "mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_mourenewal" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "renewed_at" datetime NOT NULL, "notes" text NULL, "original_mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED, "renewed_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "renewed_mou_id" bigint NOT NULL REFERENCES "mous_mou" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "mous_moutemplate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE, "description" text NULL, "template_notes" text NULL, "fields_schema" text NOT NULL CHECK ((JSON_VALID("fields_schema") OR "fields_schema" IS NULL)), "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" bigint NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "notifications_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "description" text NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "metadata" text NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)));
CREATE TABLE "permissions_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "codename" varchar(100) NOT NULL UNIQUE, "description" text NULL);
CREATE TABLE "roles_role" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "description" text NULL);
CREATE TABLE "roles_rolepermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "permission_id" bigint NOT NULL REFERENCES "permissions_permission" ("id") DEFERRABLE INITIALLY DEFERRED, "role_id" bigint NOT NULL REFERENCES "roles_role" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_customuser" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "phone" varchar(20) NULL, "designation" varchar(100) NULL, "department" varchar(100) NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "role_id" bigint NULL REFERENCES "roles_role" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_customuser_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_customuser_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "customuser_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "users_userpermission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_granted" bool NOT NULL, "permission_id" bigint NOT NULL REFERENCES "permissions_permission" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "users_customuser" ("id") DEFERRABLE INITIALLY DEFERRED);
